313 | class FFParameters {
314 |   FFParameters(this.state, [this.asyncParams = const {}]);
315 | 
316 |   final GoRouterState state;
317 |   final Map<String, Future<dynamic> Function(String)> asyncParams;
318 | 
319 |   Map<String, dynamic> futureParamValues = {};
320 | 
321 |   // Parameters are empty if the params map is empty or if the only parameter
322 |   // present is the special extra parameter reserved for the transition info.
323 |   bool get isEmpty =>
324 |       state.allParams.isEmpty ||
325 |       (state.allParams.length == 1 &&
326 |           state.extraMap.containsKey(kTransitionInfoKey));
327 |   bool isAsyncParam(MapEntry<String, dynamic> param) =>
328 |       asyncParams.containsKey(param.key) && param.value is String;
329 |   bool get hasFutures => state.allParams.entries.any(isAsyncParam);
330 |   Future<bool> completeFutures() => Future.wait(
331 |         state.allParams.entries.where(isAsyncParam).map(
332 |           (param) async {
333 |             final doc = await asyncParams[param.key]!(param.value)
334 |                 .onError((_, __) => null);
335 |             if (doc != null) {
336 |               futureParamValues[param.key] = doc;
337 |               return true;
338 |             }
339 |             return false;
340 |           },
341 |         ),
342 |       ).onError((_, __) => [false]).then((v) => v.every((e) => e));
343 | 
344 |   dynamic getParam<T>(
345 |     String paramName,
346 |     ParamType type, {
347 |     bool isList = false,
348 |     List<String>? collectionNamePath,
349 |   }) {
350 |     if (futureParamValues.containsKey(paramName)) {
351 |       return futureParamValues[paramName];
352 |     }
353 |     if (!state.allParams.containsKey(paramName)) {
354 |       return null;
355 |     }
356 |     final param = state.allParams[paramName];
357 |     // Got parameter from `extras`, so just directly return it.
358 |     if (param is! String) {
359 |       return param;
360 |     }
361 |     // Return serialized value.
362 |     return deserializeParam<T>(
363 |       param,
364 |       type,
365 |       isList,
366 |       collectionNamePath: collectionNamePath,
367 |     );
368 |   }
369 | }
