18 | Future<void> translateHtmlFile(
19 |     String inputFileName, String outputFileName) async {
20 |   try {
21 |     // Get the external storage directory
22 |     final directory = await getExternalStorageDirectory();
23 |     if (directory == null) {
24 |       throw Exception("Could not find external storage directory.");
25 |     }
26 | 
27 |     final inputFile = File('${directory.path}/$inputFileName');
28 | 
29 |     if (!await inputFile.exists()) {
30 |       throw Exception("Input file does not exist.");
31 |     }
32 | 
33 |     // Read the content of the input file
34 |     final htmlContent = await inputFile.readAsString();
35 | 
36 |     // Extract text content from the HTML
37 |     final textRegex = RegExp(r'>(.*?)<');
38 |     final matches = textRegex.allMatches(htmlContent);
39 | 
40 |     final translator = GoogleTranslator();
41 | 
42 |     // Translate all extracted text content to Marathi
43 |     Map<String, String> translations = {};
44 |     for (var match in matches) {
45 |       final originalText = match.group(1)?.trim() ?? '';
46 |       if (originalText.isNotEmpty && !translations.containsKey(originalText)) {
47 |         final translation = await translator.translate(originalText, to: 'mr');
48 |         translations[originalText] = translation.text; // Use the text property
49 |       }
50 |     }
51 | 
52 |     // Replace the original text in the HTML with the translated text
53 |     String translatedHtmlContent = htmlContent;
54 |     translations.forEach((original, translated) {
55 |       translatedHtmlContent =
56 |           translatedHtmlContent.replaceAll('>$original<', '>$translated<');
57 |     });
58 | 
59 |     // Write the translated content to the output file
60 |     final outputFile = File('${directory.path}/$outputFileName');
61 |     await outputFile.writeAsString(translatedHtmlContent);
62 | 
63 |     print(
64 |         "Translation completed. Translated file saved as: ${outputFile.path}");
65 |   } catch (e) {
66 |     print("Error during translation: $e");
67 |   }
68 | }
