extension ListDivideExtension<T extends Widget> on Iterable<T> {
  List<Widget> divide(Widget t) {
    final result = <Widget>[];
    for (final widget in this) {
      if (result.isNotEmpty) result.add(t);
      result.add(widget);
    }
    return result;
  }
}

